<template><el-card v-loading="loading"><template #header>运营统计</template><div class="filters"><el-date-picker v-model="dates" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期"/><el-button :disabled="loading" @click="load">查询</el-button><el-button :disabled="loading||!report" @click="download">导出 Excel</el-button></div><el-alert v-if="error" title="统计加载失败，请重试" type="error" :closable="false"/><template v-if="report"><p>{{report.definition}}</p><el-table :data="report.days" border><el-table-column prop="date" label="上海日期" width="120"/><el-table-column label="支付(元)"><template #default="s">{{formatPrice(s.row.paidCents)}}</template></el-table-column><el-table-column label="退款(元)"><template #default="s">{{formatPrice(s.row.refundedCents)}}</template></el-table-column><el-table-column label="净收款(元)"><template #default="s">{{formatPrice(s.row.netCents)}}</template></el-table-column><el-table-column prop="newUsers" label="新增用户"/><el-table-column prop="orders" label="新订单"/><el-table-column prop="cancelledClosed" label="取消关闭"/><el-table-column prop="reservedPeople" label="子场次名额"/><el-table-column label="确认率"><template #default="s">{{s.row.eligibleOrders?((s.row.confirmedOrders/s.row.eligibleOrders)*100).toFixed(1)+'%':'—'}}</template></el-table-column></el-table><h3>商品毛销售排名</h3><el-empty v-if="!report.rankings.length" description="此区间暂无已支付商品"/><el-table :data="report.rankings"><el-table-column prop="itemType" label="类型"/><el-table-column prop="name" label="商品"/><el-table-column prop="quantity" label="数量"/><el-table-column label="销售额(元)"><template #default="s">{{formatPrice(s.row.salesCents)}}</template></el-table-column></el-table></template></el-card></template>
<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {get,http} from '@/api/http'
import {formatPrice} from '@/utils/format'
interface Day{date:string;paidCents:number;refundedCents:number;netCents:number;newUsers:number;orders:number;cancelledClosed:number;reservedPeople:number;confirmedOrders:number;eligibleOrders:number}
interface Report{days:Day[];rankings:{itemType:string;name:string;quantity:number;salesCents:number}[];definition:string}
const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date()),dates=ref<[string,string]>([today,today]),report=ref<Report>(),loading=ref(false),error=ref(false)
const params=()=>({from:dates.value?.[0],to:dates.value?.[1]})
async function load(){loading.value=true;error.value=false;try{report.value=await get<Report>('/admin/reports',{params:params()})}catch{error.value=true;report.value=undefined}finally{loading.value=false}}
async function download(){loading.value=true;try{const blob=await http.get('/admin/reports/export',{params:params(),responseType:'blob'}) as unknown as Blob;const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='citygo-report.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}finally{loading.value=false}}
onMounted(load)
</script><style scoped>.filters{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:20px}p{line-height:1.8}</style>
